Lemma rdn_frame (M M' : word -> option byte) F : frame_but F M M' ->
  forall n a, 0 <= a -> a + Z.of_nat n <= 2 ^ 64 -> (forall i, a <= i < a + Z.of_nat n -> outside F i) ->
